const std = @import("std");
const QMAX:usize=32; const ROOTS:usize=65; const ARENA:usize=16384; const POOL:usize=8192; const LEVELS:usize=16;
const VMAX:i64=1000000; const SUMMAX:i64=64000000;
const Measure=struct{count:i32=0,sum:i64=0};
const Tree=struct{kind:u8=0,level:u8=0,plen:u8=0,slen:u8=0,mid:i32=-1,pre:[4]i32=@splat(0),suf:[4]i32=@splat(0),count:i32=0,sum:i64=0};
const Node=struct{arity:u8=0,child:[3]i32=@splat(0),count:i32=0,sum:i64=0};
const Root=struct{tree:i32=0,length:i32=0,sum:i64=0};
const View=struct{found:bool=false,item:i32=0,tree:i32=0};
const Split=struct{found:bool=false,item:i32=0,left:i32=0,right:i32=0};
const Ctx=struct{trees:[POOL]Tree,nodes:[POOL]Node,nt:usize,nn:usize,empty:[LEVELS]i32,ready:[LEVELS]bool,failed:bool};
fn addm(a:Measure,b:Measure)Measure{return .{.count=a.count+b.count,.sum=a.sum+b.sum};}
fn refm(c:*const Ctx,r:i32)Measure{if(r<0)return .{.count=1,.sum=-@as(i64,r)-1};const n=c.nodes[@intCast(r)];return .{.count=n.count,.sum=n.sum};}
fn treem(c:*const Ctx,r:i32)Measure{const t=c.trees[@intCast(r)];return .{.count=t.count,.sum=t.sum};}
fn allocTree(c:*Ctx)i32{if(c.nt+c.nn>=ARENA or c.nt>=POOL){c.failed=true;return 0;}const id=c.nt;c.nt+=1;c.trees[id]=.{ };return @intCast(id);}
fn allocNode(c:*Ctx)i32{if(c.nt+c.nn>=ARENA or c.nn>=POOL){c.failed=true;return 0;}const id=c.nn;c.nn+=1;c.nodes[id]=.{ };return @intCast(id);}
fn empty(c:*Ctx,l:u8)i32{if(l>=LEVELS){c.failed=true;return 0;}const k:usize=l;if(c.ready[k])return c.empty[k];const id=allocTree(c);c.trees[@intCast(id)]=.{.kind=0,.level=l,.mid=-1};c.ready[k]=true;c.empty[k]=id;return id;}
fn single(c:*Ctx,l:u8,x:i32)i32{const id=allocTree(c);const m=refm(c,x);c.trees[@intCast(id)]=.{.kind=1,.level=l,.plen=1,.pre=.{x,0,0,0},.count=m.count,.sum=m.sum};return id;}
fn makeNode(c:*Ctx,x:[]const i32,n:u8)i32{const id=allocNode(c);var out=Node{.arity=n};var m=Measure{};for(0..n)|i|{out.child[i]=x[i];m=addm(m,refm(c,x[i]));}out.count=m.count;out.sum=m.sum;c.nodes[@intCast(id)]=out;return id;}
fn deep(c:*Ctx,l:u8,p:[]const i32,pn:u8,mid:i32,s:[]const i32,sn:u8)i32{if(pn==0 or sn==0){c.failed=true;return empty(c,l);}const id=allocTree(c);var out=Tree{.kind=2,.level=l,.plen=pn,.slen=sn,.mid=mid};var m=treem(c,mid);for(0..pn)|i|{out.pre[i]=p[i];m=addm(m,refm(c,p[i]));}for(0..sn)|i|{out.suf[i]=s[i];m=addm(m,refm(c,s[i]));}out.count=m.count;out.sum=m.sum;c.trees[@intCast(id)]=out;return id;}
fn cons(c:*Ctx,l:u8,x:i32,id:i32)i32;
fn snoc(c:*Ctx,l:u8,id:i32,x:i32)i32;
fn fromItems(c:*Ctx,l:u8,x:[]const i32,n:u8)i32{var r=empty(c,l);for(0..n)|i|r=snoc(c,l,r,x[i]);return r;}
fn cons(c:*Ctx,l:u8,x:i32,id:i32)i32{const t=c.trees[@intCast(id)];if(t.kind==0)return single(c,l,x);if(t.kind==1){const e=empty(c,l+1);return deep(c,l,&.{x},1,e,&.{t.pre[0]},1);}if(t.plen<4){var p:[4]i32=@splat(0);p[0]=x;for(0..t.plen)|i|p[i+1]=t.pre[i];return deep(c,l,&p,t.plen,t.mid,&t.suf,t.slen);}const g=[_]i32{t.pre[1],t.pre[2],t.pre[3]};const mid=cons(c,l+1,makeNode(c,&g,3),t.mid);return deep(c,l,&.{x,t.pre[0]},2,mid,&t.suf,t.slen);}
fn snoc(c:*Ctx,l:u8,id:i32,x:i32)i32{const t=c.trees[@intCast(id)];if(t.kind==0)return single(c,l,x);if(t.kind==1){const e=empty(c,l+1);return deep(c,l,&.{t.pre[0]},1,e,&.{x},1);}if(t.slen<4){var s=t.suf;s[t.slen]=x;return deep(c,l,&t.pre,t.plen,t.mid,&s,t.slen+1);}const g=[_]i32{t.suf[0],t.suf[1],t.suf[2]};const mid=snoc(c,l+1,t.mid,makeNode(c,&g,3));return deep(c,l,&t.pre,t.plen,mid,&.{t.suf[3],x},2);}
fn viewL(c:*Ctx,l:u8,id:i32)View{const t=c.trees[@intCast(id)];if(t.kind==0)return .{.found=false,.tree=id};if(t.kind==1)return .{.found=true,.item=t.pre[0],.tree=empty(c,l)};const x=t.pre[0];var r:i32=0;if(t.plen>1){r=deep(c,l,t.pre[1..].ptr,t.plen-1,t.mid,&t.suf,t.slen);}else{const v=viewL(c,l+1,t.mid);if(!v.found){r=fromItems(c,l,&t.suf,t.slen);}else{const n=c.nodes[@intCast(v.item)];r=deep(c,l,&n.child,n.arity,v.tree,&t.suf,t.slen);}}return .{.found=true,.item=x,.tree=r};}
fn viewR(c:*Ctx,l:u8,id:i32)View{const t=c.trees[@intCast(id)];if(t.kind==0)return .{.found=false,.tree=id};if(t.kind==1)return .{.found=true,.item=t.pre[0],.tree=empty(c,l)};const x=t.suf[t.slen-1];var r:i32=0;if(t.slen>1){r=deep(c,l,&t.pre,t.plen,t.mid,t.suf.ptr,t.slen-1);}else{const v=viewR(c,l+1,t.mid);if(!v.found){r=fromItems(c,l,&t.pre,t.plen);}else{const n=c.nodes[@intCast(v.item)];r=deep(c,l,&t.pre,t.plen,v.tree,&n.child,n.arity);}}return .{.found=true,.item=x,.tree=r};}
fn deepL(c:*Ctx,l:u8,p:[]const i32,pn:u8,m:i32,s:[]const i32,sn:u8)i32{if(pn>0)return deep(c,l,p,pn,m,s,sn);const v=viewL(c,l+1,m);if(!v.found)return fromItems(c,l,s,sn);const n=c.nodes[@intCast(v.item)];return deep(c,l,&n.child,n.arity,v.tree,s,sn);}
fn deepR(c:*Ctx,l:u8,p:[]const i32,pn:u8,m:i32,s:[]const i32,sn:u8)i32{if(sn>0)return deep(c,l,p,pn,m,s,sn);const v=viewR(c,l+1,m);if(!v.found)return fromItems(c,l,p,pn);const n=c.nodes[@intCast(v.item)];return deep(c,l,p,pn,v.tree,&n.child,n.arity);}
fn group(c:*Ctx,l:u8,x:[]const i32,n:u8,out:*[8]i32)u8{var k:u8=0;var p:u8=0;while(p<n){const rem=n-p;const take:u8=if(rem==2 or rem==4)2 else 3;if(rem==1){c.failed=true;return k;}out[k]=makeNode(c,x[p..],take);k+=1;p+=take;}return k;}
fn append3(c:*Ctx,l:u8,a:i32,x:[]const i32,xn:u8,b:i32)i32{const A=c.trees[@intCast(a)];const B=c.trees[@intCast(b)];if(A.kind==0){var r=b;var i:usize=xn;while(i>0){i-=1;r=cons(c,l,x[i],r);}return r;}if(B.kind==0){var r=a;for(0..xn)|i|r=snoc(c,l,r,x[i]);return r;}if(A.kind==1){var r=b;var i:usize=xn;while(i>0){i-=1;r=cons(c,l,x[i],r);}return cons(c,l,A.pre[0],r);}if(B.kind==1){var r=a;for(0..xn)|i|r=snoc(c,l,r,x[i]);return snoc(c,l,r,B.pre[0]);}var all:[16]i32=@splat(0);var n:u8=0;for(0..A.slen)|i|{all[n]=A.suf[i];n+=1;}for(0..xn)|i|{all[n]=x[i];n+=1;}for(0..B.plen)|i|{all[n]=B.pre[i];n+=1;}var nodes:[8]i32=@splat(0);const nn=group(c,l,&all,n,&nodes);const mid=append3(c,l+1,A.mid,&nodes,nn,B.mid);return deep(c,l,&A.pre,A.plen,mid,&B.suf,B.slen);}
fn pred(mode:u8,target:i64,m:Measure)bool{return if(mode==0) @as(i64,m.count)>target else m.sum>=target;}
fn splitTree(c:*Ctx,id:i32,acc:Measure,mode:u8,target:i64)Split{const t=c.trees[@intCast(id)];if(t.kind==0)return .{.found=false,.right=id};if(t.kind==1){if(pred(mode,target,addm(acc,refm(c,t.pre[0]))){const e=empty(c,t.level);return .{.found=true,.item=t.pre[0],.left=e,.right=e};}return .{.found=false,.left=id,.right=empty(c,t.level)};}var cur=acc;for(0..t.plen)|i|{cur=addm(cur,refm(c,t.pre[i]));if(pred(mode,target,cur)){const left=fromItems(c,t.level,&t.pre,@intCast(i));const right=deepL(c,t.level,t.pre[i+1..].ptr,t.plen-@as(u8,@intCast(i))-1,t.mid,&t.suf,t.slen);return .{.found=true,.item=t.pre[i],.left=left,.right=right};}}var ap=acc;for(0..t.plen)|i|ap=addm(ap,refm(c,t.pre[i]));const mid=treem(c,t.mid);const through=addm(ap,mid);if(pred(mode,target,through)){const sm=splitTree(c,t.mid,ap,mode,target);if(!sm.found){c.failed=true;return .{.right=id};}const nd=c.nodes[@intCast(sm.item)];var ca=addm(ap,treem(c,sm.left));var before:[3]i32=@splat(0);var after:[3]i32=@splat(0);var nb:u8=0;var na:u8=0;var pivot:i32=0;var found=false;for(0..nd.arity)|i|{const next=addm(ca,refm(c,nd.child[i]));if(!found and pred(mode,target,next)){pivot=nd.child[i];found=true;}else if(!found){before[nb]=nd.child[i];nb+=1;ca=next;}else{after[na]=nd.child[i];na+=1;}}if(!found){c.failed=true;return .{.right=id};}return .{.found=true,.item=pivot,.left=deepR(c,t.level,&t.pre,t.plen,sm.left,&before,nb),.right=deepL(c,t.level,&after,na,sm.right,&t.suf,t.slen)};}cur=through;var before:[4]i32=@splat(0);for(0..t.slen)|i|{cur=addm(cur,refm(c,t.suf[i]));if(pred(mode,target,cur)){const left=deepR(c,t.level,&t.pre,t.plen,t.mid,&before,@intCast(i));const right=fromItems(c,t.level,t.suf[i+1..].ptr,t.slen-@as(u8,@intCast(i))-1);return .{.found=true,.item=t.suf[i],.left=left,.right=right};}before[i]=t.suf[i];}return .{.found=false,.left=id,.right=empty(c,t.level)};}
fn itemValue(x:i32)i64{return -@as(i64,x)-1;}
fn put(out:[*]u8,off:usize,v:i64)void{const bits=@as(u64,@bitCast(v));for(0..8)|i|out[off+i]=@truncate(bits>>(8*i));}

export fn measured_finger_tree_sequence(in_opt:?[*]const i64,len:usize,out_opt:?[*]u8,cap:usize)i64{
 if(in_opt==null or len<2 or len>195)return -1;const in=in_opt.?;const n0=in[0];if(n0<0 or n0>32)return -1;const n:usize=@intCast(n0);if(len<n+2)return -1;const qv=in[n+1];if(qv<1 or qv>32)return -1;const q:usize=@intCast(qv);if(len!=n+2+5*q or len>194)return -1;
 var c=std.mem.zeroes(Ctx);var t=empty(&c,0);for(0..n)|i|{const v=in[1+i];if(v<0 or v>VMAX)return -1;t=snoc(&c,0,t,@intCast(-v-1));}if(c.failed)return -1;const im=treem(&c,t);if(im.count>64 or im.sum>SUMMAX)return -1;var roots=[_]Root{.{}}**ROOTS;roots[0]=.{.tree=t,.length=im.count,.sum=im.sum};var nr:usize=1;var at=n+2;var records=[_]i64{0}**(QMAX*7);
 for(0..q)|op|{const tag=in[at];const aa=in[at+1];const bb=in[at+2];const x=in[at+3];const y=in[at+4];at+=5;if(tag<0 or tag>6 or aa<0 or aa>=nr or nr>=ROOTS)return -1;const a:usize=@intCast(aa);const src=roots[a].tree;var res:i32=0;var res2:i32=0;var right:i32=-1;var aux:i64=-1;var two=false;
  if(tag<=1){if(bb != -1 or y != -1 or x<0 or x>VMAX or roots[a].length>=64 or roots[a].sum+x>SUMMAX)return -1;const item:i32=@intCast(-x-1);res=if(tag==0)cons(&c,0,item,src) else snoc(&c,0,src,item);}
  else if(tag<=3){if(bb != -1 or x != -1 or y != -1 or roots[a].length==0)return -1;const v=if(tag==2)viewL(&c,0,src) else viewR(&c,0,src);if(!v.found)return -1;res=v.tree;aux=itemValue(v.item);}
  else if(tag==4){if(bb<0 or bb>=nr or x != -1 or y != -1)return -1;const b:usize=@intCast(bb);if(roots[a].length+roots[b].length>64 or roots[a].sum+roots[b].sum>SUMMAX)return -1;res=append3(&c,0,src,&.{},0,roots[b].tree);}
  else{if(bb != -1 or y != -1 or (tag==5 and (x<0 or x>roots[a].length)) or (tag==6 and (x<1 or x>SUMMAX)))return -1;const s=splitTree(&c,src,.{},if(tag==5)0 else 1,x);if(s.found){if(tag==5){res=s.left;res2=cons(&c,0,s.item,s.right);aux=x;}else{res=snoc(&c,0,s.left,s.item);res2=s.right;aux=treem(&c,res).count;}}else{res=src;res2=empty(&c,0);aux=if(tag==5)x else -1;}two=true;}
  if(c.failed)return -1;const lm=treem(&c,res);if(lm.count>64 or lm.sum>SUMMAX)return -1;const left:i32=@intCast(nr);roots[nr]=.{.tree=res,.length=lm.count,.sum=lm.sum};nr+=1;var rl:i32=-1;var rs:i64=-1;if(two){if(nr>=ROOTS)return -1;const rm=treem(&c,res2);if(rm.count>64 or rm.sum>SUMMAX)return -1;right=@intCast(nr);rl=rm.count;rs=rm.sum;roots[nr]=.{.tree=res2,.length=rm.count,.sum=rm.sum};nr+=1;}const o=op*7;records[o]=left;records[o+1]=lm.count;records[o+2]=lm.sum;records[o+3]=right;records[o+4]=rl;records[o+5]=rs;records[o+6]=aux;
 }
 const bytes=56*q;if(out_opt==null or cap<bytes)return -2;var staged=[_]u8{0}**1792;for(0..q*7)|i|put(&staged,8*i,records[i]);const out=out_opt.?;for(0..bytes)|i|out[i]=staged[i];return @intCast(bytes);
}
